UPDATE businesses SET description = 'Tambati Overnight and Conference is a bed and breakfast in Penina Park, Polokwane, offering affordable yet luxurious overnight accommodation with 17 fully furnished rooms. The property has lush gardens, a sparkling pool, a children''s play area and recreation areas, and it is set just outside the noise of the city.

Its bed and breakfast suits business travellers, backpackers, tourists and holidaymakers, and guests can book single, double, twin and luxury rooms. The property offers ample parking and security, and its website describes a warm and inviting atmosphere with efficient service. Tambati also has a fully featured conference facility for meetings and events.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://tambati.co.za/'), description_enriched_at = datetime('now') WHERE slug = 'tambati-overnight-and-conference-center-penina-park' AND description = 'Tambati Overnight and Conference Center is a guesthouse in Penina Park offering ground-floor rooms with private bathrooms, air-conditioning and garden views, alongside a garden sun terrace, outdoor swimming pool and a fully equipped conference facility for meetings and events.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
-- orchid-aesthetic-clinic-sterpark (researched)
UPDATE businesses SET description = 'Orchid Aesthetics is an aesthetic clinic in Sterpark, Polokwane, offering botox and tissue fillers for ageing skin and facial rejuvenation. Its treatments also include anti-ageing solutions, acne treatment, chemical peels, cellulite treatment, medical weight loss, detox programmes and vitamin drips for IV hydration.

The clinic lists prices for some treatments on its website, including crow''s feet at R2,100, brow lifts from R1,400 and nasolabial lifts from R2,800. Patients are asked to book an appointment by phone or email, or through the online portal. The clinic presents several of its treatments as non-surgical options for people who want to feel good about their appearance.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.orchidaesthetics.co.za/'), description_enriched_at = datetime('now') WHERE slug = 'orchid-aesthetic-clinic-sterpark' AND description = 'Orchid Aesthetic Clinic is a medical aesthetics clinic in Sterpark, Polokwane, offering treatments including Botox and dermal fillers, thread lifting, chemical peels, microneedling, PRP therapy and medical weight-loss programmes, alongside beauty services such as massages, waxing and nail treatments.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
